#include "six.hpp"
#include <iostream>
#include <iomanip>
#include <cstdlib>
int wmain(int argc,wchar_t** argv){try{
 if(argc!=4&&argc!=5)throw std::invalid_argument("Usage: six_estimate IMAGE QR_ASSETS MODEL [MTIME_UNIX_SECONDS]");cv::setNumThreads(1);auto image=qrwithbar::detail::read_gray(argv[1]),before=image.clone();if(image.cols!=3840||image.rows!=2160)throw std::invalid_argument("Expected3840x2160 uint8 image");std::filesystem::path assets=argv[2];auto reference=qrwithbar::detail::read_gray(assets/"reference.png");six::Frame r;r.warps=qrwithbar::detail::align_qrs(reference,assets);r.observation=qrwithbar::detail::analytic_observe(reference,r.warps);six::Frame frame;frame.warps=qrwithbar::detail::align_qrs(image,assets);auto initial=qrwithbar::detail::analytic_observe(image,frame.warps);if(r.observation.failures||initial.failures)throw std::runtime_error("Initialization failed");frame.observation=qrwithbar::detail::interpolated_observe(image,reference,frame.warps,r.warps,initial,r.observation,2);if(frame.observation.failures)throw std::runtime_error("Image measurement failed");six::Row row;row.x=six::describe(frame,r);if(argc==5){wchar_t* end=nullptr;row.time=std::wcstod(argv[4],&end);if(end==argv[4]||*end||!std::isfinite(row.time))throw std::invalid_argument("Invalid timestamp");}auto model=six::load_model(argv[3]);auto result=model.config.method==4?six::direct_refine(model,row,frame,r,image,reference):six::predict(model,row.x,row.time);if(cv::norm(image,before,cv::NORM_INF)!=0)throw std::runtime_error("Input modified");std::cout<<std::setprecision(17)<<"{\"t_deg\":"<<result.t<<",\"t_ticks\":"<<result.t/.01<<",\"tick_deg\":0.01,\"method\":"<<model.config.method<<",\"known_session\":"<<(result.known_session?"true":"false")<<",\"outside_T_training_range\":"<<((result.t<model.min_t||result.t>model.max_t)?"true":"false")<<",\"cost\":";bool hasCost=model.config.method==2||model.config.method==4||(model.config.method==1&&model.config.representation==0);if(hasCost)std::cout<<result.cost;else std::cout<<"null";std::cout<<"}\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
